Üç sensör için kalibrasyon sonucu elde edildi. Bu kod ne yazar?

```
const int N = 3;
int enAz[N] = {163, 500, 163};
int enCok[N] = {860, 640, 860};
const int MIN_KONTRAST = 200;

void setup() {
  Serial.begin(9600);
  bool tamam = true;
  for (int i = 0; i < N; i++) {
    Serial.print((enAz[i] + enCok[i]) / 2);
    Serial.print(' ');
    if (enCok[i] - enAz[i] < MIN_KONTRAST) tamam = false;
  }
  Serial.println(tamam ? "TAMAM" : "HATA");
}
void loop() {}
```

